from pathlib import Path


def replace_once(path, old, new, label):
    p = Path(path)
    text = p.read_text()
    if text.count(old) != 1:
        raise SystemExit(f'{label}: expected one anchor, got {text.count(old)}')
    p.write_text(text.replace(old, new, 1))

# Collected/deferred attributes need the same symbol-aware consumer as suffix
# attributes, but only external-linkage object routing opts into it.
replace_once(
    'src/frontend/parser_attribute.c',
    '''bool minic_parser_parse_gnu_object_attribute_lists_with_symbol_metadata(\n''',
    '''bool minic_parser_apply_object_attribute_list_with_symbol_metadata(\n    MinicParser *parser,\n    const MinicParsedAttributeList *attributes,\n    char *section_name,\n    size_t section_capacity,\n    size_t *section_name_length,\n    bool *has_section,\n    size_t *explicit_alignment,\n    MinicSymbolVisibility *visibility,\n    bool *has_visibility,\n    bool *is_weak) {\n    MinicObjectAttributeContext context;\n    size_t index;\n\n    if (parser == NULL || attributes == NULL || visibility == NULL || has_visibility == NULL ||\n        is_weak == NULL ||\n        !initialize_object_attribute_context(&context,\n                                             section_name,\n                                             section_capacity,\n                                             section_name_length,\n                                             has_section,\n                                             explicit_alignment)) {\n        return false;\n    }\n    context.visibility = visibility;\n    context.has_visibility = has_visibility;\n    context.is_weak = is_weak;\n    for (index = 0U; index < attributes->count; ++index) {\n        if (!consume_object_attribute(parser, &attributes->values[index], &context)) {\n            return false;\n        }\n    }\n    return true;\n}\n\nbool minic_parser_parse_gnu_object_attribute_lists_with_symbol_metadata(\n''',
    'symbol-aware collected attribute helper')

replace_once(
    'src/frontend/parser_internal.h',
    '''bool minic_parser_parse_gnu_object_attribute_lists_with_symbol_metadata(\n''',
    '''bool minic_parser_apply_object_attribute_list_with_symbol_metadata(\n    MinicParser *parser,\n    const MinicParsedAttributeList *attributes,\n    char *section_name,\n    size_t section_capacity,\n    size_t *section_name_length,\n    bool *has_section,\n    size_t *explicit_alignment,\n    MinicSymbolVisibility *visibility,\n    bool *has_visibility,\n    bool *is_weak);\nbool minic_parser_parse_gnu_object_attribute_lists_with_symbol_metadata(\n''',
    'symbol-aware collected attribute declaration')

