if text.count(old) != 1:
    raise SystemExit(f'object weak local anchor: {text.count(old)}')
text = text.replace(old, new, 1)
old = '''    visibility = MINIC_SYMBOL_VISIBILITY_DEFAULT;\n    has_visibility = false;\n'''
new = '''    visibility = MINIC_SYMBOL_VISIBILITY_DEFAULT;\n    has_visibility = false;\n    object_is_weak = false;\n'''
if text.count(old) != 1:
    raise SystemExit(f'object weak init anchor: {text.count(old)}')
text = text.replace(old, new, 1)

old = '''        if (!minic_parser_apply_object_attribute_list(parser,\n                                                      &deferred_attributes,\n                                                      section_name,\n                                                      sizeof(section_name),\n                                                      &section_name_length,\n                                                      &has_section,\n                                                      &object_explicit_alignment) ||\n            !minic_parser_apply_object_attribute_list(parser,\n                                                      &declarator_attributes,\n                                                      section_name,\n                                                      sizeof(section_name),\n                                                      &section_name_length,\n                                                      &has_section,\n                                                      &object_explicit_alignment)) {\n            return false;\n        }\n        if (is_extern_declaration) {\n'''
new = '''        if (!minic_parser_apply_object_attribute_list_with_symbol_metadata(\n                parser,\n                &deferred_attributes,\n                section_name,\n                sizeof(section_name),\n                &section_name_length,\n                &has_section,\n                &object_explicit_alignment,\n                &visibility,\n                &has_visibility,\n                &object_is_weak) ||\n            !minic_parser_apply_object_attribute_list_with_symbol_metadata(\n                parser,\n                &declarator_attributes,\n                section_name,\n                sizeof(section_name),\n                &section_name_length,\n                &has_section,\n                &object_explicit_alignment,\n                &visibility,\n                &has_visibility,\n                &object_is_weak)) {\n            return false;\n        }\n        if (is_extern_declaration) {\n'''
# There are two object branches; the first is static. Replace the second exact block
# immediately preceding is_extern_declaration.
if text.count(old) != 1:
    raise SystemExit(f'external collected attribute block: {text.count(old)}')
text = text.replace(old, new, 1)

old = '''        if (!minic_parser_parse_gnu_object_attribute_lists(parser,\n                                                           section_name,\n                                                           sizeof(section_name),\n                                                           &section_name_length,\n                                                           &has_section,\n                                                           &object_explicit_alignment)) {\n            return false;\n        }\n        if (parser->current.kind == MINIC_TOKEN_LBRACKET) {\n            return parse_visible_external_array(parser,\n                                                return_type,\n                                                name_span,\n                                                section_name,\n                                                sizeof(section_name),\n                                                &section_name_length,\n                                                &has_section,\n                                                &object_explicit_alignment,\n                                                visibility,\n                                                has_visibility);\n        }\n        if (parser->current.kind == MINIC_TOKEN_SEMICOLON) {\n            return parse_external_tentative_object(parser,\n                                                   return_type,\n                                                   name_span,\n                                                   section_name,\n                                                   section_name_length,\n                                                   has_section,\n                                                   object_explicit_alignment,\n                                                   visibility,\n                                                   has_visibility);\n        }\n        return parse_external_object_definition(parser,\n                                                return_type,\n                                                name_span,\n                                                section_name,\n                                                section_name_length,\n                                                has_section,\n                                                object_explicit_alignment,\n                                                visibility,\n                                                has_visibility);\n'''
new = '''        if (!minic_parser_parse_gnu_object_attribute_lists_with_symbol_metadata(\n                parser,\n                section_name,\n                sizeof(section_name),\n                &section_name_length,\n                &has_section,\n                &object_explicit_alignment,\n                &visibility,\n                &has_visibility,\n                &object_is_weak)) {\n            return false;\n        }\n        if (parser->current.kind == MINIC_TOKEN_LBRACKET) {\n            if (!parse_visible_external_array(parser,\n                                              return_type,\n                                              name_span,\n                                              section_name,\n                                              sizeof(section_name),\n                                              &section_name_length,\n                                              &has_section,\n                                              &object_explicit_alignment,\n                                              visibility,\n                                              has_visibility)) {\n                return false;\n            }\n        } else if (parser->current.kind == MINIC_TOKEN_SEMICOLON) {\n            if (!parse_external_tentative_object(parser,\n                                                 return_type,\n                                                 name_span,\n                                                 section_name,\n                                                 section_name_length,\n                                                 has_section,\n                                                 object_explicit_alignment,\n                                                 visibility,\n                                                 has_visibility)) {\n                return false;\n            }\n        } else if (!parse_external_object_definition(parser,\n                                                     return_type,\n                                                     name_span,\n                                                     section_name,\n                                                     section_name_length,\n                                                     has_section,\n                                                     object_explicit_alignment,\n                                                     visibility,\n                                                     has_visibility)) {\n            return false;\n        }\n        if (object_is_weak) {\n            MinicGlobalObjectId object_id;\n\n            object_id = minic_parser_find_global_object_entity(parser, name_span);\n            if (object_id == MINIC_GLOBAL_OBJECT_INVALID ||\n                !minic_c0_global_object_set_weak(parser->program, object_id, true)) {\n                minic_parser_error(parser, "GNU weak requires external object linkage");\n                return false;\n            }\n        }\n        return true;\n'''
if text.count(old) != 1:
    raise SystemExit(f'external suffix/dispatch block: {text.count(old)}')
text = text.replace(old, new, 1)
p.write_text(text)
